import React from 'react';
import Navbar from "../Homepage/Header/Navbar";


function ProfessorDetails(props) {
    const {professor, professorList, onChangeProfessor, isHome} = props;
    return (
        <>
            <div>
                    <Navbar professorList={professorList} onChangeProfessor={onChangeProfessor} isHome={isHome}/>
                    <h1>{professor.name}</h1>
            </div>

        </>
    );
}

export default ProfessorDetails;
